"""The committed 10.4 km fixture, data/tiles/synthetic-far: written by synthetic_far.py,
never by hand, and its expected.json is what every reader of tile origins is held to."""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pytest

import splat_tiles
import synthetic_far
from rig_tiles import glb_spz, tile_uris
from synthetic_tree import checksum_positions

REPO_ROOT = Path(__file__).resolve().parents[3]
#: Regenerated by:
#:   cd tools/captures && OPENBLAS_CORETYPE=Sandybridge \
#:     uv run python synthetic_far.py ../../data/tiles/synthetic-far
FAR = REPO_ROOT / "data" / "tiles" / "synthetic-far"


def _files(folder: Path) -> dict[str, bytes]:
    return {
        p.relative_to(folder).as_posix(): p.read_bytes()
        for p in sorted(folder.rglob("*"))
        if p.is_file()
    }


@pytest.fixture(scope="module")
def expected() -> dict:
    return json.loads((FAR / "source" / "expected.json").read_text(encoding="utf-8"))


def test_committed_far_fixture_matches_the_generator(tmp_path: Path) -> None:
    """Not hand-edited, not stale: the generator writes it again byte for byte (conftest
    pins the OpenBLAS kernel the parents' `eigh` runs on)."""
    stats = synthetic_far.generate(tmp_path / "far")
    fresh, committed = _files(tmp_path / "far"), _files(FAR)
    assert sorted(fresh) == sorted(committed)
    assert fresh == committed
    assert stats["offset_tiles"] >= 4 and stats["min_fractional_bits"] <= 11


def test_expected_json_names_every_tile_with_its_composed_offset(expected: dict) -> None:
    tileset = json.loads((FAR / "splat" / "tileset.json").read_text(encoding="utf-8"))
    offsets = splat_tiles.tile_offsets(tileset)
    assert sorted(expected["tiles"]) == sorted(tile_uris(tileset)) == sorted(offsets)
    moved = 0
    for uri, row in expected["tiles"].items():
        assert row["offset"] == offsets[uri].tolist()
        moved += any(row["offset"])
        columns = splat_tiles.unpack_spz(glb_spz(FAR / "splat" / uri))
        local = np.stack([columns["x"], columns["y"], columns["z"]], axis=1).astype("<f4")
        local[local == 0.0] = 0.0
        assert row["gaussians"] == local.shape[0]
        assert row["checksum"] == checksum_positions(
            splat_tiles.site_positions(local, offsets[uri])
        )
    assert moved >= 4
    assert set(expected["plotLeaves"]) == set(synthetic_far.PLOTS)
    assert all(expected["plotLeaves"].values())
